#include <cassert>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#ifdef NDEBUG
#error "Tests require assertions enabled."
#endif
// 밀리초 이상 지속할 최소 틱 수: 정수 올림. 이 예제의 입력 범위를 제한한다.
std::uint64_t ticksAtLeast(std::uint64_t ms, std::uint64_t hz) {
    if(ms>1000000 || hz==0 || hz>1000) throw std::invalid_argument("range");
    return (ms*hz+999)/1000;
}
enum class Phase { Startup, Active, Recovery, Ready };
Phase phaseAt(unsigned tick) {
    // 시작 틱은0. 반열린 구간을 사용해 경계 중복을 막는다.
    if(tick<6) return Phase::Startup;    // [0,6): 6틱
    if(tick<9) return Phase::Active;     // [6,9): 3틱
    if(tick<20) return Phase::Recovery;  // [9,20): 11틱
    return Phase::Ready;
}
int main() {
    assert(ticksAtLeast(0,60)==0);
    assert(ticksAtLeast(100,60)==6);
    assert(ticksAtLeast(101,60)==7);
    assert(ticksAtLeast(100,30)==3);
    assert(ticksAtLeast(100,120)==12);
    assert(ticksAtLeast(1000000,1000)==1000000);
    assert(phaseAt(0)==Phase::Startup && phaseAt(5)==Phase::Startup);
    assert(phaseAt(6)==Phase::Active && phaseAt(8)==Phase::Active);
    assert(phaseAt(9)==Phase::Recovery && phaseAt(19)==Phase::Recovery);
    assert(phaseAt(20)==Phase::Ready && phaseAt(1000000)==Phase::Ready);
    // 0～1000ms, 1～240Hz에서 올림 결과의 두 경계를 검사한다.
    for(std::uint64_t hz=1;hz<=240;++hz) for(std::uint64_t ms=0;ms<=1000;++ms) {
        const std::uint64_t n=ticksAtLeast(ms,hz);
        assert(n*1000>=ms*hz);
        if(n>0) assert((n-1)*1000<ms*hz);
    }
    int rejected=0;
    try { ticksAtLeast(1,0); } catch(const std::invalid_argument&) { ++rejected; }
    try { ticksAtLeast(1,1001); } catch(const std::invalid_argument&) { ++rejected; }
    try { ticksAtLeast(1000001,60); } catch(const std::invalid_argument&) { ++rejected; }
    assert(rejected==3);
    std::cout<<"frame tests passed: 240240 conversion cases\n";
}
